WITH car AS (SELECT DISTINCT REPLACE(id_imovel,'-','') id_car_norm FROM `basedosdados.br_sfb_sicar.area_imovel` WHERE data_extracao>=DATE '2026-06-02' AND data_extracao<=DATE '2026-08-04'),p AS (SELECT DISTINCT id_referencia_bacen,numero_ordem,REPLACE(id_car,'-','') id_car_norm FROM `basedosdados.br_bcb_sicor.recurso_publico_propriedade` WHERE ano_emissao BETWEEN 2013 AND 2026 AND id_car IS NOT NULL AND TRIM(id_car)!=''),x AS (SELECT op.ano_emissao,op.id_referencia_bacen,op.numero_ordem FROM p JOIN car USING(id_car_norm) JOIN `basedosdados.br_bcb_sicor.operacao` op USING(id_referencia_bacen,numero_ordem) WHERE op.ano_emissao BETWEEN 2013 AND 2026) SELECT ano_emissao,COUNT(DISTINCT id_referencia_bacen) operacoes,COUNT(*) linhas FROM x GROUP BY ano_emissao ORDER BY ano_emissao